WITH valid AS (SELECT id, customer_id, plan, start_date, monthly_fee, status, ADD_MONTHS(start_date, 6) AS start_date_plus_months FROM subscriptions WHERE start_date >= DATE '2023-11-21' AND customer_id IS NOT NULL AND customer_id IN (3, 36)), scored AS (SELECT *, LAG(monthly_fee, 1) OVER (PARTITION BY plan ORDER BY start_date, id) AS prev_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date_plus_months, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_6_prior FROM valid), with_dims AS (SELECT src.*, p.country FROM scored src JOIN customers p ON src.customer_id = p.id), ranked AS (SELECT * FROM with_dims QUALIFY ROW_NUMBER() OVER (PARTITION BY plan ORDER BY monthly_fee_avg_6_prior DESC, id) = 1), with_windows AS (SELECT *, SUM(monthly_fee) OVER (PARTITION BY plan ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY start_date_plus_months DESC, id) AS event_seq, FIRST_VALUE(prev_monthly_fee, TRUE) OVER (PARTITION BY status ORDER BY start_date_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_prev_monthly_fee, NTILE(3) OVER (PARTITION BY status ORDER BY prev_monthly_fee DESC, id) AS prev_monthly_fee_bucket, LEAD(monthly_fee_avg_6_prior, 1) OVER w_ordered AS next_monthly_fee_avg_6_prior FROM ranked WINDOW w_ordered AS (PARTITION BY plan ORDER BY monthly_fee_avg_6_prior, id)), with_dims_subscriptions AS (SELECT a.*, p.name FROM with_windows a LEFT JOIN customers p ON a.customer_id = p.id), by_type AS (SELECT * FROM (SELECT customer_id, status, first_known_prev_monthly_fee FROM with_dims_subscriptions) src PIVOT (AVG(first_known_prev_monthly_fee) AS total FOR status IN ('ACTIVE', 'EXPIRED', 'CANCELLED'))) SELECT s.customer_id, s.EXPIRED, s.CANCELLED, (SELECT MAX(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM by_type s ORDER BY max_subscription_monthly_fee DESC, customer_id;
